let controleur;

async function rechercher(terme) {
  controleur?.abort();
  controleur = new AbortController();
  try {
    const response = await fetch("/api/recherche?q=" + encodeURIComponent(terme), {
      signal: controleur.signal
    });
    return await response.json();
  } catch (erreur) {
    if (erreur.name !== "AbortError") throw erreur;
    return null;
  }
}
